preConditionHook:
// RsiDivergenceAtWindowExtreme (Brian's notes ON-41, #41). Long (bullish
// divergence): the previous bar's low is the lowest low of the lookback bars
// ending at it (EL low[1] <= Lowest(low, lookback)[1]) while RSI now is above
// RSI lookback bars ago. Short (the note's .1): high[1] is the highest high and
// RSI is below RSI lookback bars ago.
// MultiWalk's WFSafe_RSI (el_wf_safe_rsi.txt in the engine repo) -- TS's RSI
// with SF = 1/Length recomputed every bar so a walkforward length change takes
// effect; NO re-seed on a length change, the averages carry over (same shape
// as WFSafe_ADX). Seeded at the study's first calculated bar (function
// CurrentBar == study CurrentBar, as measured for WFSafe_ADX):
//   NetChgAvg = (Price - Price[Length]) / Length
//   TotChgAvg = Average(AbsValue(Price - Price[1]), Length)   -- fresh mean
// then EMA-form updates Avg = Avg[1] + SF * (X - Avg[1]).
// `TotChgAvg <> 0` is an EL relational, so it carries the 2.22e-12 tolerance.
// VERIFIED with EL_WFSafeRsi_Probe.txt on @OJ 240min, two chart starts:
// drift 0 on 9,834/9,834 and 8,327/8,327 bars against an open-coded twin,
// RSI[1] == 0 on bar 1 and the prior value after, WFSafe_RSI == plain RSI at
// a fixed length (ovr 0 everywhere). scripts/rsi_replica.py replays this hook
// from the store: 9,794/9,794 and 8,287/8,287 at print precision.
// sfRsi and chgRatio are declared locals, not hook temporaries: hooks share
// one function scope and only declared names get the placement prefix, so two
// RSI rules in one strategy would otherwise redefine them.
sfRsi = 1 / rsiLength;
if (ctx.CurrentBar() == 1) {
    netChgAvg = (close[0] - close[(int)rsiLength]) / rsiLength;
    double totChg = 0.0;
    for (int i = 0; i < (int)rsiLength; ++i) {
        totChg += std::fabs(close[i] - close[i + 1]);
    }
    totChgAvg = totChg / rsiLength;
} else {
    double change = close[0] - close[1];
    netChgAvg = netChgAvg + sfRsi * (change - netChgAvg);
    totChgAvg = totChgAvg + sfRsi * (std::fabs(change) - totChgAvg);
}
chgRatio = 0.0;
if (el_ne(totChgAvg, 0.0)) chgRatio = netChgAvg / totChgAvg;
rsiVal = 50 * (chgRatio + 1);
// EL: rsiVal = WFSafe_RSI(close, rsiLength), read as rsiVal[k]: a read of the
// rsiVal VARIABLE's own history, which holds its initial 0 for every bar
// before the strategy's first evaluated one (WFSafe_RSI(...)[1] reads 0 on
// bar 1, measured). Mirrored as a zero-seeded history kept NEWEST-FIRST --
// rsiHist[k] is EL's rsiVal[k] -- of depth lookback + 1, re-seeded if the depth
// changes.
if (rsiHist.size() != (std::size_t)((int)lookback + 1)) {
    rsiHist.assign((std::size_t)((int)lookback + 1), 0.0);
}
for (std::size_t k = rsiHist.size() - 1; k > 0; --k) {
    rsiHist[k] = rsiHist[k - 1];
}
rsiHist[0] = rsiVal;
// Lowest/Highest(..)[1] open-coded as EL's Extremes: seeded at bar 1, scanning
// 2 .. lookback, strict toleranced comparison.
windowLow = low[1];
windowHigh = high[1];
for (int ii = 2; ii <= (int)lookback; ++ii) {
    if (el_lt(low[ii], windowLow)) windowLow = low[ii];
    if (el_gt(high[ii], windowHigh)) windowHigh = high[ii];
}
// rsiVal[lookback] is the zero fill until bar lookback + 1, so both twins wait
// (the EMA-lag convention of the B-list addendum).
rsiReady = ctx.CurrentBar() > (int)lookback;
